struct format_id_offset
{
    FMTID fmtid;
    DWORD dwOffset;
};

struct property_id_offset
{
    DWORD propid;
    DWORD dwOffset;
};

struct property_section_header
{
    DWORD cbSection;
    DWORD cProperties;
};

